SELECT ,  AS phase
FROM competition 
ORDER BY registration_closes_at ASC, id ASC LIMIT #{size} OFFSET #{offset}

SELECT p.id AS publicationId, c.id AS competitionId, c.name, c.entry_mode AS entryMode,
    p.published_at AS publishedAt, p.no_awards AS noAwards

ORDER BY p.no_awards, p.published_at DESC, p.id DESC LIMIT #{size} OFFSET #{offset}
